<?php require_once __DIR__.'/db.php';require_once __DIR__.'/includes/auth.php';requireAdmin();$rows=$conn->query('SELECT title,category,venue,event_date FROM events ORDER BY event_date')->fetch_all(MYSQLI_ASSOC);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Events</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="standalone"><a href="dashboard.php">← Dashboard</a><h1>Events</h1><section class="panel"><table><thead><tr><th>EVENT</th><th>CATEGORY</th><th>VENUE</th><th>DATE</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['category'])?></td><td><?=e($r['venue'])?></td><td><?=e($r['event_date'])?></td></tr><?php endforeach;?></tbody></table></section></main></body></html>